.digitaledge-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e6edf6;
    background: linear-gradient(160deg, #0c1320 0%, #111c2e 100%);
    border-radius: 18px;
}

.digitaledge-container * {
    box-sizing: border-box;
}

.digitaledge-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0a1b3a 0%, #123a7a 55%, #1f6feb 100%);
    color: #f3f8ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 32px rgba(31, 111, 235, 0.28);
    border: 1px solid rgba(88, 166, 255, 0.25);
}

.digitaledge-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.digitaledge-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #9ecbff;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.digitaledge-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6e6ff;
}

.digitaledge-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb4d4;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.digitaledge-period-counter #currentDay,
.digitaledge-period-counter #maxPeriods {
    font-weight: 800;
    color: #58a6ff;
}

.digitaledge-round-name {
    background: rgba(31, 111, 235, 0.18);
    color: #9ecbff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(88, 166, 255, 0.30);
}

.digitaledge-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd07a;
    background: rgba(255, 168, 41, 0.14);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(255, 168, 41, 0.35);
}

.digitaledge-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.digitaledge-status-card {
    background: #16243c;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #25395c;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.28);
    border-top: 4px solid #1f6feb;
}

.digitaledge-card-digital { border-top-color: #2ea0ff; }
.digitaledge-card-moat { border-top-color: #2ee6a6; }
.digitaledge-card-margin { border-top-color: #f0a830; }
.digitaledge-card-budget { border-top-color: #8b7df0; }

.digitaledge-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa0c2;
}

.digitaledge-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #e6edf6;
}

.digitaledge-card-digital .digitaledge-value { color: #2ea0ff; }
.digitaledge-card-moat .digitaledge-value { color: #2ee6a6; }
.digitaledge-card-margin .digitaledge-value { color: #f0a830; }
.digitaledge-card-budget .digitaledge-value { color: #a99bff; }

.digitaledge-sublabel {
    font-size: 0.76rem;
    color: #7e93b4;
    line-height: 1.35;
}

.digitaledge-digital-target .digitaledge-value { color: #2ee6a6; }
.digitaledge-digital-low .digitaledge-value { color: #ff7b72; }

.digitaledge-budget-over { border-top-color: #ff7b72; }
.digitaledge-budget-over .digitaledge-value { color: #ff7b72; }

.digitaledge-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: linear-gradient(90deg, #0a1b3a, #123a7a);
    color: #eaf2ff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid rgba(88, 166, 255, 0.22);
}

.digitaledge-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #9ecbff;
}

.digitaledge-briefing {
    display: flex;
    gap: 14px;
    background: #16243c;
    border-left: 5px solid #1f6feb;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.22);
}

.digitaledge-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.digitaledge-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #9ecbff;
    margin-bottom: 6px;
}

.digitaledge-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cdd9ec;
}

.digitaledge-briefing-text strong { color: #2ee6a6; }
.digitaledge-briefing-text em { color: #ffd07a; font-style: italic; }

.digitaledge-controls {
    background: #16243c;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #25395c;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.24);
}

.digitaledge-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #e6edf6;
    border-bottom: 2px solid #25395c;
    padding-bottom: 8px;
}

.digitaledge-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c4d3ea;
    margin: 14px 0 6px;
}

.digitaledge-container select,
.digitaledge-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #30496f;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0e1a2d;
    color: #e6edf6;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.digitaledge-container select:focus,
.digitaledge-container input[type="number"]:focus {
    outline: none;
    border-color: #2ea0ff;
    box-shadow: 0 0 0 3px rgba(46, 160, 255, 0.20);
}

.digitaledge-container select option {
    background-color: #0e1a2d;
    color: #e6edf6;
}

.digitaledge-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2ea0ff;
}

.digitaledge-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb4d4;
    margin-top: 4px;
}

.digitaledge-range-readout span:last-child {
    color: #2ee6a6;
    font-weight: 800;
}

.digitaledge-hint {
    font-size: 0.8rem;
    color: #7e93b4;
    margin-top: 4px;
    line-height: 1.4;
}

.digitaledge-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.digitaledge-container .btn-primary {
    background: linear-gradient(135deg, #1f6feb 0%, #2ea0ff 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 18px rgba(31, 111, 235, 0.38);
}

.digitaledge-container .btn-primary:hover {
    filter: brightness(1.08);
}

.digitaledge-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #30496f;
    color: #9fb4d4;
    background: transparent;
}

.digitaledge-container .btn-outline-secondary:hover {
    background: rgba(48, 73, 111, 0.30);
    color: #cdd9ec;
}

.digitaledge-coach {
    background: linear-gradient(135deg, #0a1b3a 0%, #15294f 100%);
    color: #dbe7fb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.30);
    border: 1px solid rgba(88, 166, 255, 0.20);
}

.digitaledge-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #58a6ff;
    margin-bottom: 8px;
}

.digitaledge-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.digitaledge-coach-body strong { color: #2ee6a6; }
.digitaledge-coach-body em { color: #ffd07a; font-style: italic; }

.digitaledge-history,
.digitaledge-chart {
    background: #16243c;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #25395c;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.24);
}

.digitaledge-history h3,
.digitaledge-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #e6edf6;
}

.digitaledge-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdd9ec;
}

.digitaledge-container table#usfHistoryTable th {
    background: #1c2e4c;
    color: #9ecbff;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2a4068;
}

.digitaledge-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #223453;
}

.digitaledge-container table#usfHistoryTable tr:nth-child(even) td {
    background: #14202f;
}

.digitaledge-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .digitaledge-container {
        padding: 14px;
    }
    .digitaledge-header h1 {
        font-size: 1.7rem;
    }
    .digitaledge-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .digitaledge-value {
        font-size: 2rem;
    }
    .digitaledge-clock {
        margin-left: 0;
    }
    .digitaledge-period-counter {
        font-size: 0.88rem;
    }
    .digitaledge-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .digitaledge-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ===== v1.1.0 completion message — append-only ===== */
.dedge-cm{background:#ffffff;border:1px solid #dfe3ea;border-radius:12px;padding:22px 24px;margin:18px 0;color:#16233a;font-family:inherit;box-shadow:0 2px 10px rgba(16,24,44,0.06);}
.dedge-cm-head{text-align:center;border-bottom:1px solid #eef0f4;padding-bottom:14px;margin-bottom:14px;}
.dedge-cm-title{font-size:15px;font-weight:600;letter-spacing:.02em;color:#2f5db0;text-transform:uppercase;}
.dedge-cm-scorewrap{margin:8px 0 2px;}
.dedge-cm-score{font-size:52px;font-weight:800;color:#2f5db0;line-height:1;}
.dedge-cm-score-max{font-size:20px;font-weight:600;color:#8a93a6;margin-left:2px;}
.dedge-cm-grade{font-size:18px;font-weight:700;color:#16233a;margin-top:4px;}
.dedge-cm-badges{margin-top:10px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap;}
.dedge-cm-badge{display:inline-block;padding:4px 12px;border-radius:999px;font-size:12px;font-weight:700;letter-spacing:.02em;}
.dedge-cm-met{background:#e8f0fb;color:#2f5db0;border:1px solid #c3d6f2;}
.dedge-cm-fail{background:#fdecec;color:#b3261e;border:1px solid #f4c7c3;}
.dedge-cm-metrics{display:flex;gap:10px;justify-content:space-between;flex-wrap:wrap;margin:6px 0 14px;}
.dedge-cm-metric{flex:1 1 0;min-width:78px;text-align:center;background:#f5f8fc;border:1px solid #e3ebf5;border-radius:9px;padding:10px 6px;}
.dedge-cm-metric-val{font-size:22px;font-weight:800;color:#2f5db0;}
.dedge-cm-metric-lbl{font-size:11px;color:#5a6377;margin-top:2px;text-transform:uppercase;letter-spacing:.02em;}
.dedge-cm-insights{background:#f9fafc;border:1px solid #eceff4;border-radius:9px;padding:12px 16px;}
.dedge-cm-insights-title{font-size:13px;font-weight:700;color:#2f5db0;margin-bottom:6px;text-transform:uppercase;letter-spacing:.02em;}
.dedge-cm-insights ul{margin:0;padding-left:18px;}
.dedge-cm-insights li{font-size:13.5px;line-height:1.5;color:#2b3242;margin-bottom:6px;}

