                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (currency in EUR millions where money).
            this.START_DIGITAL = 9;        // % digital revenue share
            this.TARGET_DIGITAL = 28;      // 18-month target, low end of sector benchmark
            this.SECTOR_HIGH = 35;         // sector benchmark high end
            this.START_MOAT = 28;          // defensibility of technical expertise (0-100)
            this.START_MARGIN = 45;        // margin health vs price war (0-100)
            this.BUDGET_CAP = 6.0;         // EUR 6.0M, board-fixed
            this.PROCESS_COST = 2.6;       // process layer must be funded to ship on time

            // Concept truths (process answers the mandate; expertise is the moat, not price).
            this.TRUE_ROOT = `process`;
            this.TRUE_LAYER = `process`;
        }

        // Locale-aware EUR money formatter. EN: "€2.6M" (symbol before).
        // ES: "2,6 M€" (symbol after, comma decimal).
        _money(millions) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const v = Math.round(Number(millions) * 10) / 10;
            if (lang === `es`) {
                return v.toFixed(1).replace(`.`, `,`) + ` M€`;
            }
            return `€` + v.toFixed(1) + `M`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    digital: this.START_DIGITAL,
                    moat: this.START_MOAT,
                    margin: this.START_MARGIN,
                    budgetUsed: 0,
                    deadlineMissed: false,
                    priceWar: false,
                    targetMissed: false,
                    digitalHistory: [this.START_DIGITAL],
                    moatHistory: [this.START_MOAT],
                    marginHistory: [this.START_MARGIN],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING/neutral mix — NOT the textbook-correct play.
                state.decisions = {
                    root: `price`,
                    layer: `product`,
                    moatFocus: 50,
                    lead: `product`,
                    secondary: `none`,
                    commit: 3.0,
                    tradeoff: `vague`,
                    selfService: 30,
                    reps: 12,
                    pricing: `match`,
                    conflict: `mandate`,
                    kpi: `revenue`,
                    curveball: `partial`,
                    pivot: `soft`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const layer = document.getElementById(`layerInput`);
                const mf = document.getElementById(`moatFocusInput`);
                if (root) decisions.root = root.value;
                if (layer) decisions.layer = layer.value;
                if (mf) decisions.moatFocus = parseInt(mf.value, 10);
                if (!Number.isFinite(decisions.moatFocus) || decisions.moatFocus < 0 || decisions.moatFocus > 100) {
                    warn(`warn_moatfocus_range`); return false;
                }
            } else if (round === 2) {
                const lead = document.getElementById(`leadInput`);
                const sec = document.getElementById(`secondaryInput`);
                const com = document.getElementById(`commitInput`);
                const tr = document.getElementById(`tradeoffInput`);
                if (lead) decisions.lead = lead.value;
                if (sec) decisions.secondary = sec.value;
                if (com) decisions.commit = parseFloat(com.value);
                if (tr) decisions.tradeoff = tr.value;
                if (!Number.isFinite(decisions.commit) || decisions.commit < 0) {
                    warn(`warn_commit_negative`); return false;
                }
                if (decisions.commit > this.BUDGET_CAP + 0.001) {
                    warn(`warn_commit_overcap`); return false;
                }
            } else if (round === 3) {
                const ss = document.getElementById(`selfServiceInput`);
                const rp = document.getElementById(`repsInput`);
                const pr = document.getElementById(`pricingInput`);
                const cf = document.getElementById(`conflictInput`);
                if (ss) decisions.selfService = parseInt(ss.value, 10);
                if (rp) decisions.reps = parseInt(rp.value, 10);
                if (pr) decisions.pricing = pr.value;
                if (cf) decisions.conflict = cf.value;
                if (!Number.isFinite(decisions.selfService) || decisions.selfService < 0 || decisions.selfService > 80) {
                    warn(`warn_selfservice_range`); return false;
                }
                if (!Number.isFinite(decisions.reps) || decisions.reps < 0 || decisions.reps > 64) {
                    warn(`warn_reps_range`); return false;
                }
            } else if (round === 4) {
                const kp = document.getElementById(`kpiInput`);
                const cv = document.getElementById(`curveballInput`);
                const pv = document.getElementById(`pivotInput`);
                const cn = document.getElementById(`convictionInput`);
                if (kp) decisions.kpi = kp.value;
                if (cv) decisions.curveball = cv.value;
                if (pv) decisions.pivot = pv.value;
                if (cn) decisions.conviction = parseInt(cn.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: digital = digital revenue share %; moat = defensibility of expertise;
            // margin = EBITDA defence; spend = EUR M committed this round.
            let digitalDelta = 0, moatDelta = 0, marginDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose where the value proposition erodes (Common Error 3 = price framing).
                if (d.root === this.TRUE_ROOT) {
                    digitalDelta += 4; moatDelta += 8; coachKey = `coach_r1_process`;
                } else if (d.root === `price`) {
                    moatDelta -= 6; marginDelta -= 6; coachKey = `coach_r1_price`;
                } else if (d.root === `product`) {
                    moatDelta -= 8; coachKey = `coach_r1_product`;
                } else {
                    digitalDelta -= 4; moatDelta -= 10; marginDelta -= 4; coachKey = `coach_r1_nothing`;
                }

                // Muylle layer hypothesis. Process answers the mandate; "all three" spreads bets.
                if (d.layer === this.TRUE_LAYER) {
                    digitalDelta += 5; moatDelta += 5;
                    if (d.root === this.TRUE_ROOT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.layer === `product`) {
                    moatDelta += 2; marginDelta += 1;
                } else if (d.layer === `business`) {
                    marginDelta += 2; moatDelta -= 2;
                } else {
                    digitalDelta -= 5; moatDelta -= 8; marginDelta -= 4; coachKey = `coach_r1_spread`;
                }

                // Naming the expertise moat as the battleground (not price).
                if (d.moatFocus >= 60) { moatDelta += 5; }
                else if (d.moatFocus <= 25) { moatDelta -= 6; marginDelta -= 2; coachKey = `coach_r1_lowmoat`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.layer === this.TRUE_LAYER) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Place the bet: fund a lead at depth, sequence the rest (Common Errors 1 & 2).
                let leadCost = 0;
                if (d.lead === `process`) leadCost = 2.6;
                else if (d.lead === `product`) leadCost = 3.8;
                else leadCost = 4.4;

                let secCost = 0;
                if (d.secondary === `product`) secCost = 2.2;
                else if (d.secondary === `business`) secCost = 2.0;
                else secCost = 0;

                spend = d.commit;

                // The process layer is what answers the 1 September Hanssen mandate.
                const fundedProcess = (d.lead === `process` && d.commit >= this.PROCESS_COST - 0.001);
                const triedProcessUnderfunded = (d.lead === `process` && d.commit < this.PROCESS_COST - 0.001);

                if (d.lead === `process`) {
                    digitalDelta += 9; marginDelta += 7; moatDelta += 4; coachKey = `coach_r2_process`;
                } else if (d.lead === `business`) {
                    // Highest-margin idea but 18 months — misses the deadline (Common Error 2).
                    ds.deadlineMissed = true;
                    digitalDelta -= 2; marginDelta -= 8; coachKey = `coach_r2_business`;
                } else {
                    // Product layer: 14 months, also misses the immediate mandate.
                    ds.deadlineMissed = true;
                    digitalDelta += 2; moatDelta += 3; marginDelta -= 4; coachKey = `coach_r2_product`;
                }

                if (triedProcessUnderfunded) {
                    // Underfunded process ships late and misses the cutoff anyway.
                    ds.deadlineMissed = true;
                    digitalDelta -= 6; marginDelta -= 6; coachKey = `coach_r2_underfund`;
                }

                // Secondary investment, sequenced as a second bet.
                if (d.secondary === `product`) { digitalDelta += 2; moatDelta += 4; }
                else if (d.secondary === `business`) { marginDelta += 3; digitalDelta += 1; }
                else { /* reserve held — rewarded via the trade-off discipline below */ }

                // Budget discipline: committing + secondary cost beyond the cap is over-reach.
                const totalPlanned = Math.max(spend, leadCost) + secCost;
                if (totalPlanned > this.BUDGET_CAP + 0.001) {
                    marginDelta -= 6; moatDelta -= 4; coachKey = `coach_r2_overcap`;
                }

                // Trade-off discipline (Common Error 1 = pretend you can do it all).
                if (d.tradeoff === `named`) { moatDelta += 5; marginDelta += 3; if (fundedProcess) coachKey = `coach_r2_disciplined`; }
                else if (d.tradeoff === `deny`) { digitalDelta -= 4; moatDelta -= 6; marginDelta -= 4; coachKey = `coach_r2_deny`; }

                summaryKey = (fundedProcess && d.tradeoff !== `deny` && totalPlanned <= this.BUDGET_CAP + 0.001) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Channel mix & reallocation (Common Error 4 = ignore the sales force).
                // Self-service share: a moderate-high band frees reps without stranding the team.
                if (d.selfService >= 40 && d.selfService <= 60) {
                    digitalDelta += 8; coachKey = `coach_r3_balanced`;
                } else if (d.selfService > 60) {
                    digitalDelta += 4; moatDelta -= 6; coachKey = `coach_r3_toofast`;
                } else if (d.selfService >= 20) {
                    digitalDelta += 3;
                } else {
                    digitalDelta -= 2; coachKey = `coach_r3_tooslow`;
                }

                // Reps moved from order-taking to solution selling protect & extend the moat.
                if (d.reps >= 10 && d.reps <= 30) { moatDelta += 7; marginDelta += 3; coachKey = (d.selfService >= 40 && d.selfService <= 60) ? `coach_r3_reallocate` : coachKey; }
                else if (d.reps > 30) { moatDelta += 2; marginDelta -= 4; coachKey = `coach_r3_toomany`; }
                else if (d.reps === 0) { moatDelta -= 6; coachKey = `coach_r3_noreps`; }
                else { moatDelta += 4; }

                // Digital channel pricing relative to assisted channels.
                if (d.pricing === `premium`) { marginDelta += 9; moatDelta += 4; }
                else if (d.pricing === `match`) { marginDelta += 1; }
                else { // undercut = surrender margin (Common Error 3)
                    ds.priceWar = true;
                    marginDelta -= 12; moatDelta -= 6; coachKey = `coach_r3_undercut`;
                }

                // Conflict mechanism (the difference between adding revenue and just relocating it).
                if (d.conflict === `credit`) { digitalDelta += 6; moatDelta += 4; }
                else if (d.conflict === `mandate`) { digitalDelta -= 4; moatDelta -= 4; coachKey = `coach_r3_mandate`; }
                else { digitalDelta -= 6; moatDelta -= 5; coachKey = `coach_r3_noconflict`; }

                summaryKey = (d.pricing === `premium` && d.conflict === `credit` && d.reps >= 10) ? `sum_r3_good` : (d.pricing === `undercut` || d.conflict === `none` ? `sum_r3_paper` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the plan, price-war curveball, KPIs & pivot (Common Error 5).
                if (d.kpi === `adoption`) { digitalDelta += 6; moatDelta += 5; marginDelta += 4; coachKey = `coach_r4_adoption`; }
                else if (d.kpi === `revenue`) { digitalDelta += 1; moatDelta -= 2; coachKey = `coach_r4_revenue`; }
                else { digitalDelta -= 4; moatDelta -= 8; coachKey = `coach_r4_launch`; }

                // The pure-play's 8% quote — the central test of the whole case.
                if (d.curveball === `value`) {
                    marginDelta += 11; moatDelta += 6; coachKey = (d.kpi === `adoption`) ? `coach_r4_value` : coachKey;
                } else if (d.curveball === `partial`) {
                    marginDelta -= 5; moatDelta -= 2; coachKey = `coach_r4_partial`;
                } else { // match the 8% cut
                    ds.priceWar = true;
                    marginDelta -= 16; moatDelta -= 10; coachKey = `coach_r4_match`;
                }

                // Pivot trigger governs the second layer (transformation by measured adoption).
                if (d.pivot === `defined`) { moatDelta += 4; digitalDelta += 3; }
                else if (d.pivot === `soft`) { moatDelta -= 1; }
                else { moatDelta -= 6; coachKey = (d.curveball === `value`) ? coachKey : `coach_r4_nopivot`; }

                // Conviction nudges moat (defending the value of expertise).
                moatDelta += Math.round((d.conviction - 60) / 10);

                // Final settlement: a missed 1 September cutoff costs revenue and margin that
                // no late-round polish recovers — sequencing under the deadline was the point.
                if (ds.deadlineMissed) { digitalDelta -= 6; marginDelta -= 5; }

                summaryKey = (d.kpi === `adoption` && d.curveball === `value` && d.pivot === `defined`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (budget committed accumulates, capped at EUR 6.0M).
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // KPIs move on their deltas, bounded 0-100 (digital is a % share, also 0-100).
            ds.digital = Math.max(0, Math.min(100, ds.digital + digitalDelta));
            ds.moat = Math.max(0, Math.min(100, ds.moat + moatDelta));
            ds.margin = Math.max(0, Math.min(100, ds.margin + marginDelta));

            ds.digitalHistory.push(Math.round(ds.digital));
            ds.moatHistory.push(Math.round(ds.moat));
            ds.marginHistory.push(Math.round(ds.margin));

            // v1.1.0 fix: persist instructor-card composite every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            if (round === this.ROUNDS.length && ds.digital < this.TARGET_DIGITAL) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                digital: Math.round(ds.digital),
                digitalDelta: Math.round(digitalDelta),
                moat: Math.round(ds.moat),
                moatDelta: Math.round(moatDelta),
                margin: Math.round(ds.margin),
                marginDelta: Math.round(marginDelta),
                budgetUsed: ds.budgetUsed,
                deadlineMissed: ds.deadlineMissed,
                priceWar: ds.priceWar,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`digitalDisplay`, `domainState.digital`, (v) => {
                const card = document.querySelector(`.digitaledge-card-digital`);
                if (card) {
                    card.classList.toggle(`digitaledge-digital-target`, Number(v) >= this.TARGET_DIGITAL);
                    card.classList.toggle(`digitaledge-digital-low`, Number(v) < this.TARGET_DIGITAL);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`moatDisplay`, `domainState.moat`, (v) => Math.round(v));
            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => Math.round(v));

            const budgetFmt = (v) => {
                const used = this._money(Number(v));
                const cap = this._money(this.BUDGET_CAP);
                return used + ` / ` + cap;
            };
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, budgetFmt);
            uiManager.bind(`budgetCardDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.digitaledge-card-budget`);
                if (card) card.classList.toggle(`digitaledge-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return budgetFmt(v);
            });

            // Moat-focus slider readout.
            const mf = document.getElementById(`moatFocusInput`);
            const mfReadout = document.getElementById(`moatFocusReadout`);
            if (mf && mfReadout) {
                mfReadout.textContent = mf.value;
                mf.addEventListener(`input`, function() { mfReadout.textContent = mf.value; });
            }

            // Self-service slider readout.
            const ss = document.getElementById(`selfServiceInput`);
            const ssReadout = document.getElementById(`selfServiceReadout`);
            if (ss && ssReadout) {
                ssReadout.textContent = ss.value;
                ss.addEventListener(`input`, function() { ssReadout.textContent = ss.value; });
            }
        }

        getChartConfig() {
            return {
                digitalChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_digital`),
                                data: [],
                                borderColor: `#2ea0ff`,
                                backgroundColor: `rgba(46,160,255,0.16)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2ea0ff`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_moat`),
                                data: [],
                                borderColor: `#2ee6a6`,
                                backgroundColor: `rgba(46,230,166,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2ee6a6`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_margin`),
                                data: [],
                                borderColor: `#f0a830`,
                                backgroundColor: `rgba(240,168,48,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#f0a830`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#cdd9ec`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#8aa0c2` }, grid: { color: `rgba(137,160,194,0.12)` },
                                title: { display: true, text: this._cl(`axis_scale`), color: `#8aa0c2` }
                            },
                            x: {
                                ticks: { color: `#8aa0c2` }, grid: { color: `rgba(137,160,194,0.08)` },
                                title: { display: true, text: this._cl(`axis_round`), color: `#8aa0c2` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const labels = ds.digitalHistory.map((_, i) => (i === 0 ? t(`chart_start`) : t(`chart_round_prefix`) + i));
            return {
                digitalChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.digitalHistory },
                        { data: ds.moatHistory },
                        { data: ds.marginHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const digital = Math.round(ds.digital);
            const moat = Math.round(ds.moat);
            const margin = Math.round(ds.margin);
            return Math.round(digital * 0.30 + moat * 0.40 + margin * 0.30);
        }

        _cl(key) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const digital = Math.round(ds.digital);
            const moat = Math.round(ds.moat);
            const margin = Math.round(ds.margin);

            const hitTarget = digital >= this.TARGET_DIGITAL;
            const moatHeld = moat >= 55;
            const marginHeld = margin >= 50;
            const priceWar = ds.priceWar || margin < 30;
            const composite = this._composite(ds);

            let performanceKey = `grade_stuck`;
            if (hitTarget && moatHeld && marginHeld && composite >= 62) performanceKey = `grade_edge`;
            else if (hitTarget && moatHeld) performanceKey = `grade_roadmap`;
            else if (hitTarget && priceWar) performanceKey = `grade_marginlost`;
            else if (hitTarget) performanceKey = `grade_moatlost`;
            else if (digital > this.START_DIGITAL + 8) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);
            const met = hitTarget && moatHeld && marginHeld;

            const insights = [];
            if (hitTarget && moatHeld && marginHeld) insights.push(window.mySimulation.t(`insight_edge`));
            else if (hitTarget && priceWar) insights.push(window.mySimulation.t(`insight_pricewar`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thinmoat`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.deadlineMissed) insights.push(window.mySimulation.t(`insight_deadline`));
            if (moat < 45) insights.push(window.mySimulation.t(`insight_commoditized`));
            if (digital >= this.SECTOR_HIGH) insights.push(window.mySimulation.t(`insight_sector`));
            if (hitTarget && moatHeld && marginHeld) insights.push(window.mySimulation.t(`insight_amplified`));

            return {
                digital: digital,
                moat: moat,
                margin: margin,
                hitTarget: hitTarget,
                moatHeld: moatHeld,
                priceWar: priceWar,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="dedge-cm-badge ` + (s.met ? `dedge-cm-met` : `dedge-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (!s.hitTarget) badges.push(`<span class="dedge-cm-badge dedge-cm-fail">` + t(`cm_fail_target`) + `</span>`);
            if (s.priceWar) badges.push(`<span class="dedge-cm-badge dedge-cm-fail">` + t(`cm_fail_pricewar`) + `</span>`);
            if (s.hitTarget && !s.moatHeld) badges.push(`<span class="dedge-cm-badge dedge-cm-fail">` + t(`cm_fail_moat`) + `</span>`);
            const kpi = (label, val) => `<div class="dedge-cm-metric"><div class="dedge-cm-metric-val">` + val + `</div><div class="dedge-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_digital`), (s.digital != null ? s.digital : 0) + `%`) + kpi(t(`cm_moat`), (s.moat != null ? s.moat : 0)) + kpi(t(`cm_margin`), (s.margin != null ? s.margin : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="dedge-cm">`
                + `<div class="dedge-cm-head"><div class="dedge-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="dedge-cm-scorewrap"><span class="dedge-cm-score">` + score + `</span><span class="dedge-cm-score-max">/100</span></div>`
                + `<div class="dedge-cm-grade">` + grade + `</div>`
                + `<div class="dedge-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="dedge-cm-metrics">` + kpis + `</div>`
                + `<div class="dedge-cm-insights"><div class="dedge-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.deadlineMissed && state.currentPeriod >= 2) return window.mySimulation.t(`hint_deadline`);
            if (ds.priceWar) return window.mySimulation.t(`hint_pricewar`);
            if (ds.moat < 35) return window.mySimulation.t(`hint_moat`);
            if (state.currentPeriod >= 3 && ds.digital < 18) return window.mySimulation.t(`hint_behind`);
            if (ds.digital >= this.TARGET_DIGITAL && ds.moat >= 55 && ds.margin >= 50) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.digital`, label: `Digital`, i18nKey: `col_digital`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.moat`, label: `Moat`, i18nKey: `col_moat`, formatter: (v) => Math.round(v) },
                { key: `results.margin`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

